+static inline
+int _strbuf_vsnprintf(wmem_strbuf_t *strbuf, const char *format, va_list ap, gboolean reset)
 {
-    va_list ap2;
-    gsize append_len;
-
-    G_VA_COPY(ap2, ap);
-
-    append_len = g_printf_string_upper_bound(fmt, ap);
